    "triggerZh": "【触发·抽卡】抽 1 张牌。”}]}**注意：原日文效果描述中“自分の手札を1枚場外に置く”意为“将自己的一张手牌放置到场外”，这通常指弃掉或移出游戏，但根据 UNION ARENA TCG 的常见机制和上下文（如《刀剑神域》系列），更可能是指将一张手牌**从游戏中移除**（即弃置）。然而，严格遵循原文翻译，“场外”对应“场外”。若原意是“抽卡并丢弃一张”，则译为“抽1张牌，并将自己的一张手牌作为代价舍弃。”但根据指令要求“不添加原文不存在的内容”，此处直译保留“放置到场外”的表述可能不够准确。考虑到游戏机制，“场外”通常指弃堆或移除区。**修正：在 UNION ARENA 中，“場外”即指弃置（Discard）区域**。因此，标准翻译应为：“抽1张牌，并将自己的一张手牌置于弃置。”但指令要求保留“场外”。**最终决定：严格直译并符合术语表定义。“场外=场外”**。故译为：**【登场时】抽 1 张牌，将手札中的 1 张放置到场外。**",
