    "effect": "[レイド]\n〈シノン〉アクティブにし、フロントLに移動できる\nこのキャラがアタックしてバトルに勝利した時、自分の山札の上から2枚見る。その中から望む枚数を望む順で自分の山札の上に置き、残りを望む順で下に置く。自分の場の他のキャラを1枚まで選び、このターン中、BP+1000。\n[登場時]\nこのキャラはこのターン中、\n[狙い撃ち]\n（相手のフロントLのキャラを指定してアタックでき、指定した場合、相手はブロックできない）を得る。",
    "effectZh": "[Raid] \n〈希恩诺〉激活并移动至前线 L\n当该角色攻击并在战斗中获得胜利时，查看自己山札上方的 2 张卡。从中按任意顺序将想要的数量置于上方，其余的按任意顺序置于下方。从自己场上选择最多 1 个其他角色，本回合内 BP+1000。\n[登场时]\n该角色在本回合中,\n[精准射击] \n（指定对手前线 L 的角色进行攻击；若已指定则对手无法阻挡）",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[Raid] \n将此卡加入手牌或满足必要能量时，发动 Raid。",
