    "effectZh": "[Raid]\n〈尤娜〉激活并移动到前线L\n[登场时]\n本回合中，下次从手牌使用的［特征：歌］的消耗AP-1。\n[启动主]\n[回合 1]\n将自己在场外的卡片按任意顺序选择4张放置在自己的山札下方。如此做的情况下，自己场上的［特征：SAO幸存者］最多选 1 张，本回合中，\n[伤害（2）]\n（当该角色通过攻击直接造成伤害时，代替造成 2 点伤害）。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
